-- PostGIS for distance search (Technical.md 3.11). Supabase has it available; the local Docker
-- image (postgis/postgis) already includes it.
CREATE EXTENSION IF NOT EXISTS postgis;
--> statement-breakpoint
CREATE TABLE "plz" (
	"plz" text PRIMARY KEY NOT NULL,
	"city" text NOT NULL,
	"places" text[] NOT NULL,
	"location" geography(Point, 4326) NOT NULL
);
--> statement-breakpoint
ALTER TABLE "repair_request" ADD COLUMN "location" geography(Point, 4326);--> statement-breakpoint
CREATE INDEX "plz_location_idx" ON "plz" USING gist ("location");--> statement-breakpoint
CREATE INDEX "repair_request_location_idx" ON "repair_request" USING gist ("location");
--> statement-breakpoint
-- 10815 postcodes from GeoNames (https://www.geonames.org), CC BY 4.0.
--> statement-breakpoint
-- Existing requests get the centre of their PLZ. Unknown PLZs stay without a location.
UPDATE "repair_request" r SET "location" = p."location" FROM "plz" p WHERE p."plz" = r."plz";
